"use client"

import type {
  FieldErrorProps,
  LabelProps,
  TextProps,
} from "react-aria-components"
import {
  FieldError as FieldErrorPrimitive,
  Label as LabelPrimitive,
  Text,
} from "react-aria-components"
import { twMerge } from "tailwind-merge"
import { tv } from "tailwind-variants"

import { composeTailwindRenderProps } from "@/registry/preskok/lib/primitive"

const labelStyles = tv({
  base: "select-none text-base/6 text-foreground in-disabled:opacity-50 group-disabled:opacity-50 sm:text-sm/6",
})

const descriptionStyles = tv({
  base: "block text-muted-foreground text-sm/6 in-disabled:opacity-50 group-disabled:opacity-50",
})

const fieldErrorStyles = tv({
  base: "block text-danger text-sm/6 in-disabled:opacity-50 group-disabled:opacity-50 forced-colors:text-[Mark]",
})

const fieldStyles = tv({
  base: [
    "w-full",
    "[&>[data-slot=label]+[data-slot=control]]:mt-2",
    "[&>[data-slot=label]+[data-slot=control]]:mt-2",
    "[&>[data-slot=label]+[slot='description']]:mt-1",
    "[&>[slot='description']+[data-slot=control]]:mt-2",
    "[&>[data-slot=control]+[slot=description]]:mt-2",
    "[&>[data-slot=control]+[slot=errorMessage]]:mt-2",
    "*:data-[slot=label]:font-medium",
  ],
})

const Label = ({ className, ...props }: LabelProps) => {
  return (
    <LabelPrimitive
      data-slot="label"
      {...props}
      className={labelStyles({ className })}
    />
  )
}

const Description = ({ className, ...props }: TextProps) => {
  return (
    <Text
      {...props}
      slot="description"
      className={descriptionStyles({ className })}
    />
  )
}

const FieldError = ({ className, ...props }: FieldErrorProps) => {
  return (
    <FieldErrorPrimitive
      {...props}
      className={composeTailwindRenderProps(className, fieldErrorStyles())}
    />
  )
}

const Fieldset = ({
  className,
  ...props
}: React.ComponentProps<"fieldset">) => {
  return (
    <fieldset
      className={twMerge(
        "*:data-[slot=text]:mt-1 [&>*+[data-slot=control]]:mt-6",
        className
      )}
      {...props}
    />
  )
}

const Legend = ({ className, ...props }: React.ComponentProps<"legend">) => {
  return (
    <legend
      data-slot="legend"
      {...props}
      className={twMerge(
        "text-base/6 font-semibold data-disabled:opacity-50",
        className
      )}
    />
  )
}

export { Description, FieldError, Fieldset, Legend, Label }
export { labelStyles, descriptionStyles, fieldErrorStyles, fieldStyles }
